// Source of truth: session-registry.mts. The sibling .mjs is generated by `yarn workspace @ask-llm/plugin build:hooks`; never edit it.
// Session-scoped marker registry (ADR-131, #209): lets Stop/UserPromptSubmit act on every repo this session edited.
// Every export is best-effort and must not throw (ADR-077).
import { createHash } from "node:crypto";
import { mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
export const SESSION_REGISTRY_DIRNAME = "codex-pair-sessions";
// Long TTL: the sweep only reclaims crash orphans and could otherwise hit an idle live session (ADR-131).
const DEFAULT_SESSION_REGISTRY_TTL_MS = 7 * 24 * 60 * 60 * 1000;
// A NaN override would silently disable the sweep.
const ttlOverride = Number(process.env.CODEX_PAIR_SESSION_REGISTRY_TTL_MS);
export const SESSION_REGISTRY_TTL_MS = Number.isFinite(ttlOverride) && ttlOverride > 0 ? ttlOverride : DEFAULT_SESSION_REGISTRY_TTL_MS;
// The env var is a base dir; the dedicated subdir keeps the sweep from deleting unrelated data.
export const sessionRegistryRoot = () => join(process.env.CODEX_PAIR_SESSION_REGISTRY_ROOT || tmpdir(), SESSION_REGISTRY_DIRNAME);
function hash16(value) {
    return createHash("sha256").update(String(value)).digest("hex").slice(0, 16);
}
export const sessionDir = (sessionId) => join(sessionRegistryRoot(), hash16(sessionId));
const markerEntryPath = (sessionId, markerDir) => join(sessionDir(sessionId), `${hash16(markerDir)}.json`);
export function registerMarker(sessionId, markerDir) {
    if (!sessionId || !markerDir)
        return;
    try {
        mkdirSync(sessionDir(sessionId), { recursive: true });
        const p = markerEntryPath(sessionId, markerDir);
        // Atomic tmp+rename: a torn entry would be skipped as malformed and drop the repo from the session set.
        const tmp = `${p}.tmp.${process.pid}`;
        writeFileSync(tmp, JSON.stringify({ markerDir, at: new Date().toISOString() }));
        renameSync(tmp, p);
    }
    catch {
        // best-effort (ADR-077)
    }
}
export function readRegisteredMarkers(sessionId) {
    if (!sessionId)
        return [];
    const dir = sessionDir(sessionId);
    const markers = new Set();
    let names;
    try {
        names = readdirSync(dir);
    }
    catch {
        return [];
    }
    for (const name of names) {
        if (!name.endsWith(".json"))
            continue;
        try {
            const { markerDir } = JSON.parse(readFileSync(join(dir, name), "utf8"));
            if (typeof markerDir === "string" && markerDir.length > 0)
                markers.add(markerDir);
        }
        catch {
            // skip malformed / vanished entry
        }
    }
    // Probabilistic crash-orphan sweep that never touches the reading session.
    if (Math.random() < 0.05)
        sweepStaleSessions(Date.now(), SESSION_REGISTRY_TTL_MS, sessionId);
    return [...markers];
}
export function collectSessionMarkers(cwdMarker, sessionId) {
    const set = new Set();
    if (cwdMarker)
        set.add(cwdMarker);
    for (const m of readRegisteredMarkers(sessionId))
        set.add(m);
    return [...set];
}
export function clearSession(sessionId) {
    if (!sessionId)
        return;
    try {
        rmSync(sessionDir(sessionId), { recursive: true, force: true });
    }
    catch {
        // already gone
    }
}
export function sweepStaleSessions(now, ttlMs, exceptSessionId) {
    const skip = exceptSessionId ? hash16(exceptSessionId) : null;
    let sessions;
    try {
        sessions = readdirSync(sessionRegistryRoot());
    }
    catch {
        return;
    }
    const cutoff = now - ttlMs;
    for (const s of sessions) {
        if (s === skip)
            continue;
        const sdir = join(sessionRegistryRoot(), s);
        try {
            const names = readdirSync(sdir);
            // An empty dir may be mid-registration; sweeping it would lose that pending write.
            if (names.length === 0)
                continue;
            let newest = 0;
            for (const name of names) {
                try {
                    newest = Math.max(newest, statSync(join(sdir, name)).mtimeMs);
                }
                catch {
                    // entry vanished between readdir and stat
                }
            }
            if (newest < cutoff)
                rmSync(sdir, { recursive: true, force: true });
        }
        catch {
            // skip unreadable / racing session dir
        }
    }
}
